const checkMapTypeIsWMTS = (maptype?: string) => (maptype || '').match(/^(?:base|overlay|google(?:_(?:roadmap|satellite|hybrid|terrain))?|mapbox|maplibre|osm)$/);
// m6-t6 hotfix (実装レビュー H-A) → m6-t9 (§3.1 AC2): provider（google/mapbox/maplibre）は
// Maplat 同梱タイルのテンプレート url を持たない。自動補完すると ol/source/Google.js の
// baseUrl(= options.url || 'https://tile.googleapis.com/') を汚染し、Google Maps Platform への
// createSession リクエストがプレビューサーバ宛てに誤送信される（404）。data.url に手動値が
// 残っていた場合も同様に汚染し得るため、provider は url/urls を自動補完・手動値の両方とも
// 対象から除外する（isProviderMapType の定義は source/mixin.ts が正本。addCommonOptions 経由で
// mapbox/maplibre にも同じ判定を効かせる必要があるため）

export async function mapSourceFactory(options: any, commonOptions: any) {
  if (typeof options === "string") {
    // m6-t3: baseDict エントリを破壊的に書き換えない（レビュー Minor m3）
    options = { ...(baseDict as any)[options] };
  }

  options = normalizeArg(Object.assign(options, commonOptions));
  // m6-t10 §3.5.2: 解決結果が undefined のときは label キーを実体化しない。
  // 実体化すると、settingFile 経路（:188 の Object.assign(resp, options)）で
  // 設定ファイル側の label が undefined で潰れる（Object.assign は値が undefined でも
  // own enumerable property をコピーするため）。:189 のフォールバックは resp.year であり、
  // ベースマップは year を持たないため復旧もしない。
  // label / year のどちらかが存在する場合の結果は従来と同一。
  const resolvedLabel = options.label || options.year;
  if (resolvedLabel !== undefined) options.label = resolvedLabel;
  if (checkMapTypeIsWMTS(options.maptype)) {
    const targetSrc =
      options.maptype === "base"
        ? NowMap
        : options.maptype === "overlay"
          ? TmsMap
          : options.maptype === "mapbox"
            ? MapboxMap
            : options.maptype === "maplibre"
              ? MapLibreMap
              : GoogleMap;
    if (!targetSrc.isBasemap()) {
      if (!options.homePosition) options.homePosition = options.homePos;
      if (!options.mercZoom) options.mercZoom = options.defZoom;
    } else {
      options.homePosition = options.homePos;
      options.mercZoom = options.defZoom;
    }
    delete options.homePos;
    delete options.defZoom;
    if (options.zoomRestriction) {
      options.maxZoom = options.maxZoom || options.mercMaxZoom;
      options.minZoom = options.minZoom || options.mercMinZoom;
    }
    options.zoomRestriction =
      options.mercMaxZoom =
      options.mercMinZoom =
      undefined;
    if (!options.imageExtension) options.imageExtension = "jpg";
    if (isProviderMapType(options.maptype)) {
      // m6-t9 (§3.1 AC2): H-A は自動補完由来の汚染を防いだが、data.url に手動値が
      // 残っている場合はそのまま ol/source/Google 等の baseUrl を汚染し得た（同型バグ）。
      // provider は自動補完・手動値のいずれの url/urls も使わないため、ここで確実に除去する
      delete options.url;
      delete options.urls;
    } else if (options.mapID && !options.url && !options.urls) {
      options.url = options.tms
        ? `tiles/${options.mapID}/{z}/{x}/{-y}.${options.imageExtension}`
        : `tiles/${options.mapID}/{z}/{x}/{y}.${options.imageExtension}`;
    }
    options.weiwudi = await registerMapToSW(options);
    if (options.weiwudi) {
      options.url = options.weiwudi.url;
      delete options.urls;
    }
    const obj = await targetSrc.createAsync(options);
    await obj.initialWait;
    return obj;
  } else if (options.noload) {
    options.mercMaxZoom = options.mercMinZoom = undefined;
    return new HistMap_tin(options);
  }


  const url = options.settingFile || `maps/${options.mapID}.json`;

  const response = await fetch(url);
  if (!response.ok) {
    throw new Error("Fail to load map json");
  }

  const resp = await response.json();
  options = normalizeArg(Object.assign(resp, options));
  options.label = options.label || resp.year;
  if (!options.maptype) options.maptype = "maplat";

  if (checkMapTypeIsWMTS(options.maptype)) {
    const targetSrc =
      options.maptype === "base"
        ? NowMap
        : options.maptype === "overlay"
          ? TmsMap
          : options.maptype === "mapbox"
            ? MapboxMap
            : options.maptype === "maplibre"
              ? MapLibreMap
              : GoogleMap;
    if (!targetSrc.isBasemap()) {
      if (!options.homePosition) options.homePosition = options.homePos;
      if (!options.mercZoom) options.mercZoom = options.defZoom;
    } else {
      options.homePosition = options.homePos;
      options.mercZoom = options.defZoom;
    }
    delete options.homePos;
    delete options.defZoom;
    if (options.zoomRestriction) {
      options.maxZoom = options.maxZoom || options.mercMaxZoom;
      options.minZoom = options.minZoom || options.mercMinZoom;
    }
    options.zoomRestriction =
      options.mercMaxZoom =
      options.mercMinZoom =
      undefined;
    if (!options.imageExtension) options.imageExtension = "jpg";
    if (isProviderMapType(options.maptype)) {
      // m6-t9 (§3.1 AC2): 手動値からの汚染防止（上の分岐と同型。設定 json 経由の読み込み経路）
      delete options.url;
      delete options.urls;
    } else if (options.mapID && !options.url && !options.urls) {
      options.url = options.tms
        ? `tiles/${options.mapID}/{z}/{x}/{-y}.${options.imageExtension}`
        : `tiles/${options.mapID}/{z}/{x}/{y}.${options.imageExtension}`;
    }
    options.weiwudi = await registerMapToSW(options);
    if (options.weiwudi) {
      options.url = options.weiwudi.url;
      delete options.urls;
    }
    const obj = await targetSrc.createAsync(options);
    try {
      await obj.initialWait;
      return obj;
    } catch (_e) {
      return obj;
    }
  }

  delete options.homePos;
  delete options.defZoom;
  if (!options.imageExtension) options.imageExtension = "jpg";
  if (options.mapID && !options.url && !options.urls) {
    options.url = `tiles/${options.mapID}/{z}/{x}/{y}.${options.imageExtension}`;
  }
  if (!options.compiled || !options.compiled.wh) {
    console.error(
      `[Maplat] Missing compiled.wh for mapID=${options.mapID}. Check map setting file: ${url}`
    );
    throw new Error(`Map ${options.mapID} is missing compiled data.`);
  }
  options.width = options.width || options.compiled.wh[0];
  options.height = options.height || options.compiled.wh[1];
  options.weiwudi = await registerMapToSW(options);
  if (options.weiwudi) {
    options.url = options.weiwudi.url;
    delete options.urls;
  }
  const obj = await HistMap_tin.createAsync(options);
  await obj.initialWait;
  // setupMapParameter uses callback pattern, wrap it in Promise
  await new Promise<void>((resolve) => {
    obj.setupMapParameter(() => resolve());
  });
  return obj;
}

export async function registerMapToSW(options: any) {
  const setting: any = {};
  if (options.maptype === "mapbox" || options.maptype === "maplibre" || options.maptype === "google" || !options.enableCache) return;
  else if (options.maptype === "base" || options.maptype === "overlay")
    setting.type = "wmts";
  else setting.type = "xyz";
  setting.url = options.urls ? options.urls : options.url;
  setting.width = options.width;
  setting.height = options.height;
  setting.maxZoom = options.maxZoom;
  setting.minZoom = options.minZoom;
  // タイルキャッシュ有効期間(ms)。Weiwudi側の既定は24時間 (code4history/Weiwudi#2)
  if (options.cacheTtl !== undefined) setting.cacheTtl = options.cacheTtl;
  const lngLats = options.envelopeLngLats;
  if (lngLats) {
    const minMax = lngLats.reduce(
      (prev: number[], curr: number[]) => {
        prev[0] = prev[0] > curr[0] ? curr[0] : prev[0];
        prev[1] = prev[1] < curr[0] ? curr[0] : prev[1];
        prev[2] = prev[2] > curr[1] ? curr[1] : prev[2];
        prev[3] = prev[3] < curr[1] ? curr[1] : prev[3];
        return prev;
      },
      [Infinity, -Infinity, Infinity, -Infinity]
    );
    ["minLng", "maxLng", "minLat", "maxLat"].map((key, index) => {
      setting[key] = minMax[index];
    });
  }
  let ret;
  try {
    ret = await Weiwudi.registerMap(options.mapID, setting);
  } catch (_e) {
    // Ignore error
  }
  return ret;
}
