import Layer from "ol/layer/Layer";
import { toLonLat } from "ol/proj";
import { glCanvasMatchesSize } from "./gl_canvas_size";

export class MapboxLayer extends Layer {
  constructor(options: any) {
    // m6-t9 §3.4 (実装レビュー round2 H-AC5-2): layer_maplibre.ts と同型のガードを
    // 予防的に適用する（実運用での顕在化は未確認。差分適用が効いているため潜在化している
    // と推測されるのみで、根本原因の確証は maplibre 側のみ）
    let lastAppliedStyle: unknown;
    const render = function (frameState: any) {
      // @ts-expect-error ts-migrate(2683) FIXME: 'this' implicitly has type 'any' because it does n... Remove this comment to see the full error message
      const source = this.getSource();
      const mbMap = source.mapboxMap;
      if (!mbMap) {
        console.error('MapboxLayer: mapboxMap is undefined!');
        return null;
      }
      if (source.style !== lastAppliedStyle) {
        mbMap.setStyle(source.style);
        lastAppliedStyle = source.style;
      }
      const canvas = mbMap.getCanvas();
      const viewState = frameState.viewState;
      
      // Debug canvas position
      // console.log('Mapbox canvas position:', {
      //   canvasWidth: canvas.width,
      //   canvasHeight: canvas.height,
      //   canvasOffsetLeft: canvas.offsetLeft,
      //   canvasOffsetTop: canvas.offsetTop,
      //   canvasStyle: {
      //     top: canvas.style.top,
      //     left: canvas.style.left,
      //     position: canvas.style.position
      //   }
      // });

      // @ts-expect-error ts-migrate(2683) FIXME: 'this' implicitly has type 'any' because it does n... Remove this comment to see the full error message
      const visible = this.getVisible();
      canvas.style.display = visible ? "block" : "none";

      // @ts-expect-error ts-migrate(2683) FIXME: 'this' implicitly has type 'any' because it does n... Remove this comment to see the full error message
      const opacity = this.getOpacity();
      canvas.style.opacity = opacity;

      // oct26-m2-t2（MaplatCore #100）: MapLibreLayer.render() と同型の canvas 同期 2 点を移植する。
      // (b) canvas を OpenLayers の viewport 左上へ絶対配置する。
      canvas.style.position = 'absolute';
      canvas.style.left = '0';
      canvas.style.top = '0';

      // (a) canvas 寸法を frameState.size へ同期する（MapLibreLayer と同じ比較式。GL の画素比で割って CSS ピクセル同士で比べる（#107））。
      // 下の「view 不変なら早期 return」より前に置く: view が動かずコンテナ寸法だけが変わった場合にも
      // 同期させるため。resize した frame は早期 return せず、同期描画まで進める。
      let resized = false;
      if (frameState.size) {
        const [width, height] = frameState.size;
        if (!glCanvasMatchesSize(mbMap, canvas, [width, height])) {
          mbMap.resize();
          resized = true;
        }
      }

      // adjust view parameters in mapbox
      const newBearing = (viewState.rotation * -180) / Math.PI;
      const newLonLat = toLonLat(viewState.center);
      const newZoom = viewState.zoom - 1;

      const nowBearing = mbMap.getBearing();
      const nowLonLat = mbMap.getCenter().toArray();
      const nowZoom = mbMap.getZoom();

      if (
        !resized &&
        newBearing == nowBearing &&
        newLonLat[0] == nowLonLat[0] &&
        newLonLat[1] == nowLonLat[1] &&
        newZoom == nowZoom
      ) {
        return canvas;
      }

      if (newBearing != nowBearing) {
        mbMap.rotateTo(newBearing, {
          animate: false
        });
      }
      if (
        newLonLat[0] != nowLonLat[0] ||
        newLonLat[1] != nowLonLat[1] ||
        newZoom != nowZoom
      ) {
        mbMap.jumpTo({
          center: newLonLat,
          zoom: newZoom,
          animate: false
        });
      }

      // cancel the scheduled update & trigger synchronous redraw
      // see https://github.com/mapbox/mapbox-gl-js/issues/7893#issue-408992184
      // NOTE: THIS MIGHT BREAK WHEN UPDATING MAPBOX
      if (mbMap._frame) {
        mbMap._frame.cancel();
        mbMap._frame = null;
      }

      mbMap._render();

      return canvas;
    };
    super({
      render,
      source: options.source
    });
  }
}
